class Translator:
    def __init__(self, language: str = "en") -> None:
        if language not in MESSAGES:
            raise ValueError("Supported languages are en and de")
        self.language = language

    def __call__(self, key: str) -> str:
        return MESSAGES[self.language].get(key, MESSAGES["en"].get(key, key))

    def decimal(self, value: str | Decimal | None, *, places: int = 2) -> str:
        if value is None:
            return "—"
        try:
            number = Decimal(value)
            if not number.is_finite():
                return "—"
            rendered = f"{number:,.{places}f}"
        except (InvalidOperation, ValueError, TypeError):
            return "—"
        if self.language == "de":
            return rendered.translate(str.maketrans(",.", ".,"))
        return rendered

    def parse_decimal(self, value: str) -> Decimal:
        candidate = value.strip()
        if self.language == "de":
            if "." in candidate:
                raise ValueError("Use an ungrouped decimal with a comma")
            candidate = candidate.replace(",", ".")
        elif "," in candidate:
            raise ValueError("Use an ungrouped decimal with a point")
        result = Decimal(candidate)
        if not result.is_finite():
            raise ValueError("Finite decimal required")
        return result

    def timestamp(self, value: str) -> str:
        try:
            timestamp = datetime.fromisoformat(value.replace("Z", "+00:00"))
            if timestamp.tzinfo is None:
                return value
            local = timestamp.astimezone()
            return local.strftime("%d.%m.%Y %H:%M:%S %Z" if self.language == "de" else "%Y-%m-%d %H:%M:%S %Z")
        except ValueError:
            return value
